    {
        "function": "get_email_address",
        "parameters": {
            "name": "田中さん"
        }
    },
    {
        "function": "auto_message",
        "parameters": {
            "address": "{get_email_address_result}",  // 前の関数の結果を参照
            "situation": "遅刻する旨のメール"
